<script setup>
import { Head, router } from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';
defineProps({ licenses: Array });
const dateTime=value=>value?new Intl.DateTimeFormat('en-NG',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Never';
const copy=async key=>navigator.clipboard.writeText(key);
const deactivate=activation=>{if(confirm(`Deactivate ${activation.device_name}? The product will need to be activated again on this installation.`))router.post(route('portal.licenses.activations.deactivate',activation.uuid));};
</script>
<template><Head title="Activation keys"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="licenses"/></template><div class="mb-6"><h1 class="text-3xl font-bold">Activation keys</h1><p class="mt-2 text-slate-600">Retrieve your securely stored activation keys and control the installations using them.</p></div><p v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</p><div class="space-y-5"><article v-for="license in licenses" :key="license.uuid" class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-sm font-bold text-cyan-700">{{ license.identifier }}</p><h2 class="mt-1 text-xl font-bold">{{ license.product }}</h2><p class="mt-1 text-sm text-slate-500">Expires {{ license.expires_at || 'with subscription' }} · Maximum {{ license.max_activations }} activation(s)</p></div><span class="rounded-full bg-emerald-100 px-3 py-1 text-xs font-bold uppercase text-emerald-800">{{ license.status }}</span></div><div v-if="license.license_key" class="mt-5 rounded-xl border border-cyan-200 bg-cyan-50 p-4"><p class="text-xs font-bold uppercase tracking-wider text-cyan-800">License activation key</p><div class="mt-2 flex flex-wrap items-center gap-3"><code class="break-all rounded-lg bg-white px-3 py-2 font-bold text-[#0B3D6E] ring-1 ring-cyan-200">{{ license.license_key }}</code><button type="button" class="rounded-lg bg-[#0797A5] px-4 py-2 text-sm font-bold text-white" @click="copy(license.license_key)">Copy key</button></div><p class="mt-2 text-xs text-slate-600">Keep this key private. Use it only inside the selected KernelBridge product.</p></div><div class="mt-5 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="text-slate-500"><tr><th class="py-2">Installation</th><th>Status</th><th>Activated</th><th>Last verified</th><th></th></tr></thead><tbody><tr v-for="activation in license.activations" :key="activation.uuid" class="border-t"><td class="py-3 font-semibold">{{ activation.device_name }}</td><td class="uppercase">{{ activation.status }}</td><td>{{ dateTime(activation.activated_at) }}</td><td>{{ dateTime(activation.last_verified_at) }}</td><td class="text-right"><button v-if="activation.status==='active'" type="button" class="font-bold text-red-700 hover:underline" @click="deactivate(activation)">Deactivate</button></td></tr></tbody></table><p v-if="!license.activations.length" class="py-4 text-slate-500">No installations have used this licence.</p></div></article><p v-if="!licenses.length" class="rounded-2xl bg-white p-10 text-center text-slate-500 ring-1 ring-slate-200">No activation keys have been issued to your account.</p></div></PortalLayout></template>
